        setValue(L.DESC_COMMAND_COUNT_TOKENS_RETURN, "JSON con i token, le parole e i caratteri");
        setValue(L.DESC_COMMAND_LIST_SUMMARIES, "Elenca i riassunti di un ramo e se sono validi.");
        setValue(L.DESC_COMMAND_LIST_SUMMARIES_LLM, "Elenca i riassunti che la generazione usa su un ramo, dal primo: la posizione della parte che lo ha, le parti che copre, riassunto normale o meta-riassunto, i token, se descrive ancora la storia (valido) e quanti riassunti sostituisce un meta-riassunto, poi quante parti alla fine non hanno un riassunto. Solo lettura. Le opzioni sono posizionali e facoltative, nell'ordine elencato. Ogni riga ha anche il suo \"handle\": non cambia quando si aggiunge o si elimina qualcosa, ed è ciò che i comandi che modificano il libro accettano.");
        setValue(L.DESC_COMMAND_LIST_SUMMARIES_RETURN, "JSON con i riassunti: position, covers, type, tokens, valid");
