        setValue(L.DESC_COMMAND_CHECK_SUMMARIES_RETURN, "JSON con il numero di riassunti e quelli obsoleti con le parti che coprono");
        setValue(L.DESC_COMMAND_GET_TEMPLATE_VARIABLES, "Mostra le variabili di template del libro o di una parte.");
        setValue(L.DESC_COMMAND_GET_TEMPLATE_VARIABLES_LLM, "Le variabili che i template dei prompt impostano con setvar: quelle globali del libro (scope global), oppure quelle su una parte, che seguono il suo ramo (scope part; l'ultima parte del ramo quando non viene indicata una posizione). Una parte si indica con il suo handle (l'\"handle\" degli elenchi; non cambia quando si aggiungono o si eliminano parti, quindi preferiscilo) o con la sua posizione in un ramo (la prima parte della storia è 1); il ramo è quello attivo a meno che non venga indicato l'handle di una sua parte o un numero di ramo da list-branches. Solo lettura. Le opzioni sono posizionali e facoltative, nell'ordine elencato.");
