        setValue(L.DESC_COMMAND_TURN_SCENE_PARAM, "L'ambientazione della scena del turno; vuoto la cancella, omesso la lascia com'è");
        setValue(L.DESC_COMMAND_TURN_POV_PARAM, "Il personaggio del punto di vista del turno; vuoto lo cancella, omesso lo lascia com'è");
        setValue(L.DESC_COMMAND_TURN_PRESENT_PARAM, "I personaggi presenti nel turno; vuoto li cancella, omesso li lascia come sono");
        setValue(L.DESC_COMMAND_EDIT_PART, "Sostituisce un pezzo del testo di una parte con un altro testo. Parametri: part (handle), old, new, field.");
        setValue(L.DESC_COMMAND_EDIT_PART_LLM, "Modifica una parte della storia: il pezzo di testo `old` viene sostituito da `new`. `old` deve corrispondere esattamente una volta nella parte (con gli stessi spazi e le stesse interruzioni di riga), altrimenti nulla viene modificato e l'errore dice quante volte è stato trovato: prendi più testo attorno. La parte si indica con il suo handle. Conta le sue parole e i suoi token, e dice quali riassunti sono diventati obsoleti (poi esegui revalidate-summaries se sono ancora corretti, oppure rigenerali). Con `field` vengono modificati invece le istruzioni, la scena, il punto di vista o i personaggi presenti del turno. Modifica il libro.");
        setValue(L.DESC_COMMAND_EDIT_PART_RETURN, "JSON con la parte (handle, position, words, tokens) e i riassunti diventati obsoleti");
